import unittest
from allocate import allocate


class PlacesTests(unittest.TestCase):
    def test_places_three_quantization(self):
        shares = allocate("0.003", [1, 1, 1], places=3)
        for s in shares:
            # quantized to exactly 3 decimal places
            self.assertEqual(-s.as_tuple().exponent, 3)

import unittest
from ratelimit import SlidingWindowLimiter


class ConstructorRejectTests(unittest.TestCase):
    def test_reject_negative_limit(self):
        with self.assertRaises(ValueError):
            SlidingWindowLimiter(-1, 10)
